h1 {
  font-family: 'Inter var', sans-serif;
  font-weight: 700; /* Fallback for non-variable font support */
  font-variation-settings: "wght" 700, "wdth" 100;
  letter-spacing: -0.02em;
}

@media (max-width: 768px) {
  h1 {
    font-variation-settings: "wght" 500, "wdth" 85; /* Adjust for smaller screens */
  }
}
